#!/usr/bin/env python3
"""Regenerate the offline book from editable text, screenshot metadata and images.
Run: python3 docs/editor-guide/first-space/source/build.py
Uses only the Python standard library; never changes screenshot bytes.
"""
from pathlib import Path
import json, html
BASE = Path(__file__).resolve().parent
OUT = BASE.parent
G = json.loads((BASE / 'guide.json').read_text())
SCREENSHOTS = json.loads((BASE / 'screenshots.json').read_text())
# Coordinates below are actual native menu positions, normalized to its 480×272 UI.
manual={'game-explore-empty':[(239,227),(97,227)],'game-imported':[(128,99)],'game-arrival-home':[(241.4,136.1)]}
def figure(f):
 name=f['shot'];meta=SCREENSHOTS[name];w,h=meta['size']
 if not (OUT/'images'/(name+'.webp')).is_file():raise FileNotFoundError(name)
 coords=[]
 for mark in f.get('marks',[]):
  if mark not in meta['controls']:raise ValueError(f"Missing control {mark} in {name}")
  coords.append(meta['controls'][mark])
 coords+=manual.get(name,[])
 scale=min(w/480,h/272);ox=(w-480*scale)/2;oy=(h-272*scale)/2
 marks=''
 for i,(x,y) in enumerate(coords):
  x=ox+x*scale;y=oy+y*scale
  # A small ring and arrow identify the exact native control without obscuring its text.
  dx=-86 if x>w*.65 else 86;dy=-64 if y>h*.2 else 64
  marks+=f'<path d="M{x+dx:.1f},{y+dy:.1f} L{x+dx*.22:.1f},{y+dy*.22:.1f}" stroke="#fff" stroke-width="13"/><path d="M{x+dx:.1f},{y+dy:.1f} L{x+dx*.22:.1f},{y+dy*.22:.1f}" stroke="#e22831" stroke-width="7" marker-end="url(#arrow)"/><circle cx="{x:.1f}" cy="{y:.1f}" r="{16*scale/6:.1f}" fill="none" stroke="#fff" stroke-width="9"/><circle cx="{x:.1f}" cy="{y:.1f}" r="{16*scale/6:.1f}" fill="none" stroke="#e22831" stroke-width="5"/>'
 svg=f'<svg viewBox="0 0 {w} {h}" role="img" aria-label="{html.escape(f["caption"],quote=True)}"><defs><marker id="arrow" markerWidth="4" markerHeight="4" refX="3" refY="2" orient="auto"><path d="M0,0 L4,2 L0,4" fill="#e22831"/></marker></defs><image data-src="images/{name}.webp" width="{w}" height="{h}"/>{marks}</svg>'
 # Include a readable enlargement of the menu/form around an annotated control.
 detail=''
 if coords and not name.startswith('game-'):
  detail_coords=coords if max(y for x,y in coords)-min(y for x,y in coords)<50 else coords[-2:];detail_coords=detail_coords if max(x for x,y in detail_coords)-min(x for x,y in detail_coords)<160 else [detail_coords[-1]];xs=[ox+x*scale for x,y in detail_coords];ys=[oy+y*scale for x,y in detail_coords];cx=sum(xs)/len(xs);cy=sum(ys)/len(ys)
  cw=min(w,1000);ch=min(h,380);left=max(0,min(w-cw,cx-cw/2));top=max(0,min(h-ch,cy-ch/2))
  if name in {'12-pillar-form','26-home-form','50-pool-form','56-basin-page-1','56-basin-page-2','58-water-page-1'}:left=ox+134*scale;top=oy+54*scale;cw=300*scale;ch=168*scale
  detail='<div class="detail"><span>Control close-up</span>'+svg.replace(f'viewBox="0 0 {w} {h}"',f'viewBox="{left:.0f} {top:.0f} {cw} {ch}"')+'</div>'
 return f'<figure><button class="zoom" title="Enlarge screenshot" aria-label="Enlarge: {html.escape(f["caption"],quote=True)}">{svg}</button>{detail}<figcaption>{html.escape(f["caption"])}</figcaption><a class="original" href="images/{name}.webp" target="_blank">Open full-resolution screenshot ↗</a></figure>'
nav=[];pages=[];section=''
for i,p in enumerate(G['pages']):
 if p['section']!=section:section=p['section'];nav.append('<h3>'+html.escape(section)+'</h3>')
 nav.append(f'<a href="#{p["id"]}"><span>{i+1:02}</span>{html.escape(p["title"])}</a>')
 figs=''.join(figure(f) for f in p['figures']);check=f'<aside class="checkpoint"><strong>Before you continue</strong><p>{p["checkpoint"]}</p></aside>' if p['checkpoint'] else ''
 prev=f'<a href="#{G["pages"][i-1]["id"]}">← Previous</a>' if i else '<span></span>'
 nxt=f'<a href="#{G["pages"][i+1]["id"]}">Next: {html.escape(G["pages"][i+1]["title"])} →</a>' if i+1<len(G['pages']) else '<a href="#welcome">Back to the beginning ↑</a>'
 pages.append(f'<article id="{p["id"]}"><header><p class="eyebrow">{html.escape(p["section"])} · {i+1:02} / {len(G["pages"]):02}</p><h1>{html.escape(p["title"])}</h1></header><div class="lesson {"text-only" if not figs else ""}"><div class="instructions">{p["body"]}{check}</div><div class="pictures">{figs}</div></div><footer>{prev}{nxt}</footer></article>')
css='''*{box-sizing:border-box}html{scroll-behavior:auto}body{margin:0;background:#f5f4ed;color:#202c31;font-family:Inter,ui-sans-serif,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;font-size:16px;line-height:1.65}a{color:#13665d;text-underline-offset:3px}button{font:inherit;cursor:pointer}.brand{font-size:19px;font-weight:750;line-height:1.3;letter-spacing:-.4px}.brand small{display:block;color:#3c726a;font-size:11px;letter-spacing:1.5px;margin-bottom:12px}nav{position:fixed;inset:0 auto 0 0;width:256px;overflow:auto;background:#e9eee7;padding:30px 23px;border-right:1px solid #d7dfd4}nav h3{font-size:11px;text-transform:uppercase;letter-spacing:1.6px;color:#5f746d;margin:26px 0 9px}nav a{display:flex;gap:10px;font-size:12px;line-height:1.35;padding:8px 5px;text-decoration:none;border-radius:5px}nav a span{font-variant-numeric:tabular-nums;color:#8a9790}nav a.active{background:#d4e3d7;color:#173c34;font-weight:700}main{margin-left:256px;padding:40px clamp(24px,4vw,70px) 24px;max-width:2000px}article{display:none}article.active{display:block}header{border-bottom:1px solid #c9d3c8;padding-bottom:24px;margin-bottom:30px}.eyebrow{font-size:12px;text-transform:uppercase;letter-spacing:1.6px;font-weight:700;color:#41746b;margin:0 0 12px}h1{font-size:clamp(28px,3vw,46px);line-height:1.12;letter-spacing:-1.5px;max-width:900px;margin:0}.lesson{display:grid;grid-template-columns:minmax(300px,.8fr) minmax(450px,1.2fr);gap:38px;align-items:start}.text-only{grid-template-columns:minmax(300px,780px)}p{margin:0 0 20px}ol,ul{padding-left:23px;margin:0 0 24px}li{margin:0 0 14px;padding-left:4px}strong{font-weight:700}code{font-size:.88em;overflow-wrap:anywhere;background:#e8eae3;padding:2px 4px;border-radius:3px}kbd{font-size:.84em;background:#fff;border:1px solid #c9d2ca;border-radius:4px;padding:2px 5px;white-space:nowrap}table{border-collapse:collapse;width:100%;font-size:14px;line-height:1.5;margin:22px 0}td,th{padding:11px 10px;border-bottom:1px solid #d7ddd3;text-align:left;vertical-align:top}th{background:#e5ebe0;color:#2e554c}.checkpoint{background:#e2ecdf;border-left:4px solid #43816c;padding:18px 20px;margin:28px 0}.checkpoint strong{font-size:11px;letter-spacing:1.2px;text-transform:uppercase}.checkpoint p{margin:7px 0 0}figure{margin:0 0 30px;padding:0 0 22px;border-bottom:1px solid #d7ddd3}.zoom{display:block;padding:0;border:1px solid #c4cec8;border-radius:8px;overflow:hidden;background:#19252a;width:100%;box-shadow:0 5px 17px #20332b14}.zoom svg{width:100%;display:block}.detail{margin-top:10px;background:#e9ede7;border-radius:6px;padding:9px}.detail span{font-size:10px;letter-spacing:1.5px;text-transform:uppercase;color:#5c736a;display:block;margin-bottom:7px}.detail svg{display:block;width:100%;border-radius:4px}figcaption{font-size:14px;line-height:1.5;margin:12px 0 4px;color:#405b52}.original{font-size:11px}footer{border-top:1px solid #c9d3c8;padding:24px 0;display:flex;justify-content:space-between;gap:24px;font-size:14px}footer a{text-decoration:none;font-weight:650}.mobile{display:none}dialog{border:0;padding:44px 10px 10px;background:#101b20;width:96vw;max-width:none;height:94vh;max-height:none;color:white}dialog::backdrop{background:#0b181deb}dialog .close{position:fixed;right:4vw;top:5vh;border:0;border-radius:20px;background:white;color:#16392e;padding:6px 15px;z-index:2}dialog svg{display:block;width:100%;min-width:1200px;height:auto}dialog .zoom-content{height:100%;overflow:auto}.missing{padding:30px;background:#fee;color:#900}@media(max-width:1150px){.lesson{grid-template-columns:1fr}.instructions{max-width:760px}.pictures{max-width:1000px}main{padding:30px}}@media(max-width:750px){nav{display:none;position:relative;width:auto;max-height:70vh}nav.open{display:block}main{margin:0;padding:24px 18px}.mobile{display:block;padding:12px 18px;background:#e9eee7;border:0;width:100%;text-align:left}.lesson{gap:24px}h1{font-size:33px}.detail{display:none}footer{font-size:12px}}@media print{nav,.mobile,footer,.detail,.original{display:none!important}main{margin:0;padding:0}article,article.active{display:block;break-before:page}.lesson{display:block}figure{break-inside:avoid;max-width:100%}.zoom{box-shadow:none}header{margin-bottom:15px}body{font-size:11pt;background:white}h1{font-size:25pt}.pictures{display:grid;grid-template-columns:1fr 1fr;gap:12px}}'''
js='''const chapters=[...document.querySelectorAll('article')];function show(){let id=decodeURIComponent(location.hash.slice(1))||'welcome';if(!chapters.some(x=>x.id===id))id='welcome';chapters.forEach(x=>x.classList.toggle('active',x.id===id));document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.hash==='#'+id);if(a.hash==='#'+id)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.title=chapters.find(x=>x.id===id).querySelector('h1').textContent+' · Places guide';document.querySelector('article.active').querySelectorAll('image[data-src]').forEach(im=>im.setAttribute('href',im.dataset.src));window.scrollTo(0,0)}addEventListener('hashchange',show);addEventListener('beforeprint',()=>document.querySelectorAll('image[data-src]').forEach(im=>im.setAttribute('href',im.dataset.src)));show();function stick(){document.querySelectorAll('.instructions').forEach(x=>{x.style.position=innerWidth>1150&&x.offsetHeight<innerHeight-70?'sticky':'static';x.style.top='28px'})}addEventListener('hashchange',stick);addEventListener('resize',stick);stick();document.querySelector('.mobile').onclick=()=>document.querySelector('nav').classList.toggle('open');const modal=document.querySelector('dialog');document.querySelectorAll('.zoom').forEach(b=>b.onclick=()=>{modal.querySelector('.zoom-content').innerHTML=b.innerHTML;modal.showModal()});modal.querySelector('.close').onclick=()=>modal.close();modal.onclick=e=>{if(e.target===modal)modal.close()};'''
(OUT/'index.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="data:,"><title>'+html.escape(G['title'])+'</title><style>'+css+'</style><body><button class="mobile">☰ Contents</button><nav aria-label="Guide contents"><div class="brand"><small>PLACES · FIRST SPACE</small>'+html.escape(G['title'])+'</div>'+''.join(nav)+'</nav><main>'+''.join(pages)+'</main><dialog aria-label="Enlarged screenshot"><button class="close">Close ✕</button><div class="zoom-content"></div></dialog><script>'+js+'</script></body></html>')
print(json.dumps({'lessons':len(G['pages']),'screenshot_placements':sum(len(p['figures']) for p in G['pages']),'unique_screenshots':len(SCREENSHOTS),'output':str(OUT/'index.html')}))
